import { ready, emit } from './events';
import { once } from '../utils/guards';

import './observer';
import './router';

import '../ui/header';
import '../ui/sidebar';
import '../ui/cards';
import '../ui/dashboard';
import '../ui/settings';
import '../ui/login-page';

import '../playback/backdrop';
import '../playback/media-bar';
import '../playback/osd';

import '../utils/icons';

ready(() => {
    once('ptv-core', () => {
        document.documentElement.classList.add('ptv-ready');
        emit('ready');
        console.info('[PiggieTV] Frontend initialized');
    });
});
